//! The keyboard layouts of `ukbd(4)`, `dev/usb/ukbdmap.c`: for each layout `wskbd(4)` offers
//! a USB keyboard (`KB_US`, `KB_DE`, ... and their variants), the keysyms of the keys it
//! changes, by USB HID key code (usage page 7).
//!
//! Upstream: sys/dev/usb/ukbdmap.c @ 3ce1f3f79392
//!
//! The C file is generated (by `makemap.awk` from `dev/pckbc/wskbdmap_mfii.c`); so is this
//! one, from the C, keeping every line of the tables and their comments. A table is a list
//! of entries, each a key code (`KC(n)`, a keysym of group `KS_GROUP_Keycode`), an optional
//! command keysym (`KS_Cmd_*`) and up to four keysyms (normal, shifted, altgr, shift-altgr);
//! `ukbd_keydesctab` names each layout's table and the layout it is a delta over, which
//! `wskbdutil.rs`'s `wskbd_load_keymap` applies first.
//!
//! ## Deviations
//! - `WSKBD_NO_INTL_LAYOUTS` is not defined (GENERIC has every layout): the `#if` lines are
//!   kept as comments.
//! - The macro `KC(n)` is the `const fn` [`kc`], `KBD_MAP(name, base, map)` the `const fn`
//!   `kbd_map`; the tables are `&[KeysymT]` slices (`map_size` is their length) and
//!   `ukbd_keydesctab` has no `{0, 0, 0, 0}` terminator (`wsksymvar.rs`).
//! - The C's block comments are line comments.

use crate::dev::wscons::wsksymdef::*;
use crate::dev::wscons::wsksymvar::{KeysymT, WsconsKeydesc};

/// `KC(n)`: the keysym of key code `n` (`KS_KEYCODE(n)`).
const fn kc(n: u32) -> KeysymT {
    ks_keycode(n) as KeysymT
}

/// `KBD_MAP(name, base, map)`: layout `name`, a delta over `base`, with the keymap `map`.
const fn kbd_map(name: u32, base: u32, map: &'static [KeysymT]) -> WsconsKeydesc {
    WsconsKeydesc {
        name,
        base,
        map_size: map.len() as i32,
        map,
    }
}

